--初始化高级副本信息
function EquipQuestComponent:InitialSeniorCopy(jsonData)
    self._cardsInfo = {}
    self._seniorInfo = {}
    if not jsonData then
        return 
    end
    jsonData = checkTable(jsonData)

    local t = jsonData.cardsInfo
    if t then
        for k, v in pairs(t) do
            self._cardsInfo[checkString(k)] = v
        end
    end

    t = jsonData.seniorEquipmentInfo
    if t then
        for k, v in pairs(t) do
            local questId = self:GetQuestIdByDiff(v)
            self._seniorInfo[checkString(k)] = questId--checkNumber(v)
        end
    end

    self:InitialCurSeniorQusetInfo(jsonData.equipmentQuestId, jsonData.equipmentQuestPassedId)

    -- 强行置为1
    self._isThreeTripleMode = math.max(checkInt(self._isThreeTripleMode), checkInt(jsonData.isThreeTripleMode))
end

function EquipQuestComponent:GetQuestIdByDiff(diff)
    if checkNumber(diff) == 0  then
        return 0
    end
    if not (#self._questSettingDiffMap > 0) then
        local questVo = CfUtils.GetWholeVo(AutoIds.IdSetting848, "QuestSeniorEquipVo")
        for i, v in pairs(questVo) do
            self._questSettingDiffMap[checkString(v.diff)] = v
        end
        --print("11------->>"..table.dump(questVo))
        --print("22------->>"..table.dump(self._questSettingDiffMap))
    end
    local questId = self._questSettingDiffMap[checkString(diff)].id
    return questId
end


--高级装备副本入口
function EquipQuestComponent:SeniorEquipQuestHomeReq(cb)
    GameUtils.Request(Interfaces.EquipmentQuestSeniorEquipmentHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self:InitialSeniorCopy(jsonData)

        if cb then
            cb()
        end
    end)
end

--进入一个副本
function EquipQuestComponent:EnterQuestReq(questId, cb)
    if not questId then
        return
    end
    --如果是一样的
    if checkNumber(self:GetCurSeniorQuestId()) == checkNumber(questId) then
        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIFastReliefDisasterResponseMapDialog, parameters = {questId = questId}},  {
            {id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog}
        })
        CS.Engine.UI.UIModule.PopPage()
        return
    elseif checkNumber(self:GetCurSeniorQuestId()) ~= 0 then
        GameUtils.Toast(localize("当前已有挑战关卡"))
        return
    end

    GameUtils.Request(Interfaces.EquipmentQuestEnterSeniorEquipment, {questId = questId, isThreeTripleMode = self._isThreeTripleMode}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        self._curSeniorQuestId = checkString(questId)
        self._curSeniorPassLevels = {}

        if cb then
            cb()
        end
    end)
end

--放弃一个副本
function EquipQuestComponent:GiveUpQuestReq(cb)
    GameUtils.SecondConfirm(localize("是否放弃本次挑战"), function()
        GameUtils.Request(Interfaces.EquipmentQuestRenounceQuest, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            self:SetCurSeniorLastQuestId(self:GetCurSeniorQuestId())
            CS.Engine.Lib.KCookie.Set("UISeniorEquipNodeSelect", self._curSeniorQuestId)

            self._curSeniorQuestId = 0
            self._curSeniorPassLevels = {}
            self:SetLastSubEquipPassedQuestId()
            self._cardsInfo = {}
            if cb then
                cb()
            end
            local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
            teamComponent:ClearTeamBySystemId(Constants.SystemToggleIds.Id18)
        end)
    end)
end

function EquipQuestComponent:GetPointAdd()
    if self:GetLastSubEquipPassedQuestId() <= 0 then
        return 0
    end
    ---@type QuestSeniorEquipVo
    local questVo = CfUtils.GetCfVo(AutoIds.IdSetting848, "QuestSeniorEquipVo", self:GetLastSubEquipPassedQuestId())
    ---@type QuestSeniorEquipBattleTypeVo
    local typeVo = CfUtils.GetCfVo(AutoIds.IdSetting843, "QuestSeniorEquipBattleTypeVo", questVo.pointType)
    return checkInt(typeVo.rewardCost)
end
function EquipQuestComponent:SetLastSubEquipPassedQuestId(questId)
    self.lastEquipPassQuestId = checkInt(questId)
end
function EquipQuestComponent:GetLastSubEquipPassedQuestId()
    return checkInt(self.lastEquipPassQuestId)
end

---UpdateEquipQuestStarInfo 更新低级装备副本的星级信息
---@param starInfo table 星级信息
---@param questId string 关卡id
function EquipQuestComponent:UpdatePrimaryEquipQuestStarInfo(questId, starInfo)
    if not starInfo or not questId then
        return
    end
    --达成三星的不刷新
    if not QuestConfMgr:GetInstance():IsCompleteAllCondition(questId) then
        --直接覆盖
        self._primaryInfo[checkString(questId)] = checkTable(starInfo)
    end
end

---UpdateEquipQuestStarInfo 更新高级装备副本的信息
---@param battleData table 战斗数据
function EquipQuestComponent:UpdateSeniorEquipQuestInfo(levelId, isThreeTripleMode)
    if not levelId then
        return
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(levelId)
    if vo then
        local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
        --如果是boss  则这关打通了
        --if checkNumber(vo.pointType) == Constants.RoleClass.Boss then
        --    local vo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", self._curSeniorQuestId)
            if vo then
                --跟新副本进度
                if self._seniorInfo[checkString(vo.type)] then
                    if checkNumber(self._seniorInfo[checkString(vo.type)]) < checkNumber(self._curSeniorQuestId) then 
                        self._seniorInfo[checkString(vo.type)] = checkString(self._curSeniorQuestId)
                    end 
                end 
                --打通副本后扣除门票
                if isThreeTripleMode then
                    self:SetTripleMode(isThreeTripleMode)
                end
                local triple = self:IsThreeTripleMode() and 3 or 1
                GoodsUtils.DrawRewards(
                {
                    {
                        goodsId = checkNumber(vo.costItem),
                        num = -checkNumber(vo.costNum) * triple,
                    }
                })
            end
            self:SetCurSeniorLastQuestId(self:GetCurSeniorQuestId())
            CS.Engine.Lib.KCookie.Set("UISeniorEquipNodeSelect", self._curSeniorQuestId)

            self._curSeniorQuestId = 0
            self._curSeniorPassLevels = {}
            self._cardsInfo = {}
            --如果是通关 直接清空队伍
            --teamComponent:ClearTeamBySystemId(Constants.SystemToggleIds.Id18)
        --else
        --    if not self._curSeniorPassLevels then
        --        self._curSeniorPassLevels = {}
        --    end
        --    table.insert(self._curSeniorPassLevels, checkString(levelId))
            self:SetLastSubEquipPassedQuestId(levelId)
        --end
    end
end

---IsCompleteCondition 根据星的条件id判断是否已达成
---@param levelId string 关卡id
---@param conditionId string 条件id
function EquipQuestComponent:IsCompleteCondition(levelId, conditionId)
    local levelStarInfo = self._primaryInfo[checkString(levelId)]
    if levelStarInfo then
        if checkNumber(levelStarInfo[conditionId]) == 1 then
            return true
        end
    end
    return false
end

--更新卡牌信息
function EquipQuestComponent:UpdateCardHpEngyData(cardInfo)
    if not cardInfo then
        return
    end
    cardInfo = checkTable(cardInfo)
    for k, v in pairs(cardInfo) do
        self._cardsInfo[checkString(k)] = v
    end
end

--获取装备副本的卡牌血量信息
function EquipQuestComponent:GetEquipCopyCardHpEngyData(cardId)
    if not self._cardsInfo then
        return nil
    end

    for k, v in pairs(self._cardsInfo) do
        if checkNumber(k) == checkNumber(cardId) then
            return v
        end
    end

    --如果没有这个card就是默认状态，满血0能量
    local data = {
        hpPercent = 1,
        energy = 0,
    }
    return data
end

---IsPassLevelById 是否通关关卡
---@param levelId string 关卡id 
function EquipQuestComponent:IsPassLevelById(levelId)
    if checkNumber(levelId) == 0 then
        return true
    end

    if self._curSeniorPassLevels then
        for k, v in pairs(self._curSeniorPassLevels) do
            if checkNumber(v) == checkNumber(levelId) then
                return true
            end
        end
    end

    return false
end

---IsPassQuestById 是否通关关卡/副本的一个难度
---@param levelId string 关卡id 
function EquipQuestComponent:IsPassQuestById(questId)
    if checkNumber(questId) == 0 then
        return true
    end

    questId = checkString(questId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting848, "QuestSeniorEquipVo", questId)
    --local vo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", questId)
    if not vo then
        return false
    end
    local maxPassId = self._seniorInfo[checkString(vo.type)]
    if maxPassId then
        return checkNumber(maxPassId) >= checkNumber(questId)
    end
    return false
end

---IsPassLevelById 是否解锁关卡
---@param levelId string 关卡id 
function EquipQuestComponent:IsUnlockLevelById(levelId)
    if checkNumber(levelId) == 0 then
        return true
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(levelId)
    if not vo then
        return false
    end
    return self:IsPassLevelById(vo.unlockNum)
end

---IsPassLevelById 是否解锁关卡
---@param levelId string 关卡id 
function EquipQuestComponent:IsUnlockQuestById(questId)
    if checkNumber(questId) == 0 then
        return true
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", questId)
    if not vo then
        return false
    end
    return self:IsPassQuestById(vo.unlockNum)
end

function EquipQuestComponent:GetQuestProgressById(copyId)
    return checkInt(self._seniorInfo[checkString(copyId)])
end

--是否解锁了该副本
function EquipQuestComponent:IsUnlockCopyType(copyId)
    if not copyId then
        return false
    end
    local data = self._seniorInfo[checkString(copyId)]
    if data then
        return true
    end
    return false
end

---GetCurQuestCostNum 当前副本总共有的上限
---@param questId string 副本关卡id 
function EquipQuestComponent:GetCurQuestCostNum()
    local num = 0
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", checkString(self:GetCurSeniorQuestId()))
    if not vo then
        return num
    end

    num = checkNumber(vo.initialCost)
    if self._curSeniorPassLevels then
        for k, v in pairs(self._curSeniorPassLevels) do
            num = num + self:GetLevlCostNum(v)
        end
    end
    return num
end

--获取当前挑战的高级副本id
function EquipQuestComponent:GetCurSeniorQuestId()
    return self._curSeniorQuestId
end

--获取上次挑战的高级副本id
function EquipQuestComponent:GetCurSeniorLastQuestId()
    --local t = self._lastBattleQuestId
    --self._lastBattleQuestId = nil
    return self._lastBattleQuestId
end
function EquipQuestComponent:SetCurSeniorLastQuestId(id)
    self._lastBattleQuestId = checkString(id)
end

function EquipQuestComponent:IsThreeTripleMode()
    return checkInt(self._isThreeTripleMode) == 1
end
function EquipQuestComponent:SetTripleMode(mode)
    self._isThreeTripleMode = checkInt(mode)
end

---GetLevlCostNum 获取一个关卡的cost
---@param levelId string 关卡id 
function EquipQuestComponent:GetLevlCostNum(levelId)
    local num = 0
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(levelId)
    if vo then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting843, "QuestSeniorEquipBattleTypeVo", vo.pointType)
        if vo then
            num = num + checkNumber(vo.rewardCost)
        end
    end
    return num
end

return EquipQuestComponent